<template><button class="issue-row" @click="$emit('open',item)"><div class="issue-meta"><span v-if="showDevice">{{item.device}}</span><span class="issue-type" :class="'rank-'+item.rank">{{item.type}}</span><span v-if="showState" class="issue-status">{{item.eventState || item.state}}</span><span class="issue-next">{{item.state==='已派发'?'查看进展':item.state==='待决策'?'查看分析':'查看记录'}}<span aria-hidden="true"> ›</span></span></div><strong>{{item.title}}</strong><p>{{item.state==='已派发'?'负责人：'+(item.owner||'待确认')+' · '+item.stage:compact?compactSummary:item.summary}}</p><p v-if="item.state==='已记录决定'" class="decision-note">{{item.decisionReason}}</p></button></template>
<script setup>import {computed} from 'vue'
const props=defineProps({compact:Boolean,item:Object,showDevice:{type:Boolean,default:true},showState:Boolean});defineEmits(['open'])
const compactSummary=computed(()=>props.item.id==='real-alarm-0430'?'排温偏离伴喷射反馈报警，检查二缸喷射控制与燃油供给。':props.item.id==='real-warning-0523'?'主机控制空气进口及安全监测压力下降，核实现场供气和减压环节。':props.item.id.includes('c4')?'四缸相对排温下移，结合核实反馈确认后续维保安排。':'一缸相对排温抬升，核对测温、工况和喷油调整记录。')
</script>
<style scoped>.issue-row{display:block;text-align:left;width:100%;border:0;border-bottom:1px solid #e9edf2;background:#fff;padding:14px 0;cursor:pointer;color:#445870;font:inherit}.issue-row:hover{background:#faf9f6}.issue-row:focus-visible{outline:2px solid #b49359;outline-offset:-2px}.issue-meta{display:flex;gap:10px;align-items:center;font-size:var(--wb-label);margin-bottom:7px;color:#6a7789;flex-wrap:wrap}.issue-type{padding:3px 8px;border-radius:4px;font-weight:500;line-height:1.4}.rank-0,.rank-1{color:#b93838;background:#fff0ef}.rank-2,.rank-3{color:#a56816;background:#fff5e5}.issue-status{color:#6a7789;background:#f3f5f8;padding:3px 8px;border-radius:4px}.issue-next{margin-left:auto;color:#8b682d;font-size:var(--wb-label);line-height:1.5}.issue-row strong{font-size:calc(var(--wb-body) + 2px);color:#24354c;font-weight:600;line-height:1.6}.issue-row p{font-size:var(--wb-body);line-height:1.7;margin:5px 0 0;color:#627188;overflow-wrap:anywhere}.decision-note{color:#7b6b51!important}@media(max-width:600px){.issue-next{width:100%;margin-left:0}}</style>